            if existing >= MAX_ADS_FILES:
                st.warning(f"Maksimal {MAX_ADS_FILES} file iklan tersimpan. File '{uf.name}' dilewati.")
                continue
            fname = sanitize_filename(uf.name)
            fpath = os.path.join(ADS_DATA_DIR, fname)
