smm_gadget = _smm_row(sb_gadget)
smm_all = _smm_row(sb_all)
smm_corp = _smm_row(sb_corp) if sb_corp is not None else None

omset_all_val = _sd_value(smm_all)
omset_service_val = _sd_value(smm_service)
